<template>
    <div class="container">
        <h1>{{ msg }}</h1>
        <p> hello world </p>
        <button type="button" class="btn btn-success" @click="pdfgen">Create pdf</button>
    </div>
</template>

<script>
    export default {
  name: 'Pdfgen',
  props: {
    msg: String
  },
  methods: {
    pdfgen: function () {
      var pdfMake = require('pdfmake/build/pdfmake.js')
      if (pdfMake.vfs == undefined){
        var pdfFonts = require('pdfmake/build/vfs_fonts.js')
        pdfMake.vfs = pdfFonts.pdfMake.vfs;
      }
      var docDefinition = { content: [
        'This is an sample PDF printed with pdfMake', {image: 'data:image/png;base64,'}
      ]};
      pdfMake.createPdf(docDefinition).download('ATOLcertificate.pdf')
    }
  }
    }
</script>